"""Static COSMIC.CYPHER browser surface.

Device handles stay browser-local. JavaScript sends only explicit bounded feature
observations to the loopback controller unless a future capability says otherwise.
"""
from __future__ import annotations

import json


def render_cosmic_ui(session_token: str = "local-test-session") -> str:
    return _HTML.replace("__BEAST_SESSION__", json.dumps(session_token))


_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Beast Box · COSMIC.CYPHER</title>
<style>
:root{color-scheme:dark;--bg:#04070d;--panel:#0a1120ee;--panel2:#101a2d;--line:#283550;--text:#edf4ff;--muted:#91a0b8;--cyan:#79ded5;--gold:#e8ca76;--red:#ff7e8b;--green:#8ce8a7}
*{box-sizing:border-box}html{background:var(--bg)}body{margin:0;min-height:100vh;color:var(--text);font:14px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;background:radial-gradient(ellipse at 78% 5%,#182749 0,#0a101d 25%,#050810 56%,#03050a 100%)}body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.18;background-image:radial-gradient(#dbe8ff 1px,transparent 1px);background-size:47px 47px;mask-image:linear-gradient(#000,transparent 78%)}button,input,select,textarea{font:inherit}button{cursor:pointer;border:1px solid var(--line);border-radius:9px;padding:.58rem .82rem;color:var(--text);background:#121b2e}button:hover,button:focus-visible{border-color:#7184a8;outline:none}button.danger{border-color:#68333e;background:#251116;color:#ffd9de}.app{display:grid;grid-template-columns:224px minmax(0,1fr);min-height:100vh}.rail{position:sticky;top:0;height:100vh;overflow:auto;padding:18px 14px;border-right:1px solid var(--line);background:#060a12e8;backdrop-filter:blur(18px)}.brand{font-weight:850;letter-spacing:.13em;font-size:16px;margin:4px 8px 18px}.brand small{display:block;margin-top:4px;color:var(--muted);font-size:10px;letter-spacing:.21em}.nav button{width:100%;text-align:left;margin:2px 0;background:transparent;border-color:transparent;color:#b7c3d7}.nav button.active{color:#fff;background:#111b2e;border-color:#263653}.main{position:relative;width:100%;max-width:1520px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:18px}.eyebrow{font-size:11px;font-weight:750;letter-spacing:.16em;color:var(--cyan)}h1{margin:.2rem 0;font-size:clamp(24px,3vw,38px);letter-spacing:-.025em}.statusbar{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.pill{border:1px solid var(--line);border-radius:999px;padding:5px 9px;background:#0b1220;color:var(--muted)}.pulse{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--cyan);box-shadow:0 0 15px var(--cyan);animation:pulse 1.8s ease-in-out infinite}@keyframes pulse{50%{opacity:.32;transform:scale(.75)}}.privacy{margin-bottom:14px;border:1px solid #62323d;border-radius:14px;padding:12px 14px;background:#241117bb}.view{display:none}.view.active{display:block}.grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:14px}.card{grid-column:span 4;min-height:110px;padding:15px;border:1px solid var(--line);border-radius:15px;background:linear-gradient(150deg,#10192bea,#090e19ea);box-shadow:0 18px 50px #0005}.wide{grid-column:span 8}.half{grid-column:span 6}.full{grid-column:1/-1}.label{text-transform:uppercase;letter-spacing:.1em;font-size:11px;color:var(--muted)}.value{margin-top:7px;font-size:21px;font-weight:760;word-break:break-word}.sub{margin-top:5px;color:var(--muted)}.flow{display:flex;align-items:center;justify-content:space-between;gap:7px;flex-wrap:wrap}.node{padding:10px 12px;border:1px solid var(--line);border-radius:12px;background:#0b1324}.arrow{color:#64748f}.warning{padding:9px 11px;border-left:3px solid var(--gold);background:#2b210f66;color:#fae5b1}.ok{color:var(--green)}.chatlog{height:420px;overflow:auto;padding:12px;border:1px solid var(--line);border-radius:12px;background:#050811}.msg{max-width:82%;margin:8px 0;padding:10px 12px;border-radius:12px;background:#111a2d;white-space:pre-wrap}.msg.user{margin-left:auto;background:#17233c}.composer{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;margin-top:10px}.composer textarea{min-height:78px}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.field,textarea,select,input{width:100%;padding:9px;border:1px solid var(--line);border-radius:9px;background:#070c16;color:var(--text)}video.camera{width:100%;max-height:390px;border:1px solid var(--line);border-radius:12px;background:#000}canvas.scope{width:100%;height:120px;border:1px solid var(--line);border-radius:10px;background:#05070c}.authority-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 0;border-bottom:1px solid #1d2739}.authority-row:last-child{border:0}pre{max-height:470px;overflow:auto;margin:10px 0 0;padding:12px;border:1px solid var(--line);border-radius:10px;background:#050811;white-space:pre-wrap;word-break:break-word}.trace-node{margin:7px 0;padding:7px 10px;border-left:2px solid #46617d;background:#07101c}.hidden{display:none}.live{color:#dbfff8!important;border-color:#39736f!important}
@media(max-width:920px){.app{grid-template-columns:1fr}.rail{position:relative;height:auto;border-right:0;border-bottom:1px solid var(--line)}.nav{display:flex;overflow:auto}.nav button{width:auto;white-space:nowrap}.main{padding:15px}.card,.wide,.half{grid-column:1/-1}.top{align-items:flex-start;flex-direction:column}.statusbar{justify-content:flex-start}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
</style></head><body><div class="app"><aside class="rail"><div class="brand">BEAST BOX<small>COSMIC.CYPHER</small></div><nav class="nav" id="nav">
<button class="active" data-view="orbit">ORBIT</button><button data-view="brain">BRAIN</button><button data-view="bay">BRAIN BAY</button><button data-view="vision">VISION</button><button data-view="listen">LISTEN</button><button data-view="voice">VOICE</button><button data-view="reality">REALITY</button><button data-view="memory">MEMORY VAULT</button><button data-view="trace">SYNAPSE TRACE</button><button data-view="files">FILES</button><button data-view="workspace">WORKSPACE</button><button data-view="qbay">Q-BAY</button><button data-view="connections">CONNECTIONS</button><button data-view="authority">AUTHORITY</button><button data-view="settings">SETTINGS</button></nav></aside>
<main class="main"><header class="top"><div><div class="eyebrow">OWNER-CONTROLLED PERSISTENT SUBSTRATE</div><h1>Swap the brain. Keep the story.</h1></div><div class="statusbar"><span class="pill" id="providerPill">provider —</span><span class="pill"><span class="pulse"></span> substrate</span><span class="pill" id="cloudPill">local boundary</span></div></header>
<div class="privacy"><b>MASTER PRIVACY</b> · stop camera, microphone, sensors, cloud, repository write and live experimental jobs. <button class="danger" id="masterStop">STOP ALL LIVE FLOWS</button></div>
<section id="orbit" class="view active"><div class="grid"><div class="card"><div class="label">Active brain</div><div class="value" id="brainValue">—</div><div class="sub" id="providerValue">—</div></div><div class="card"><div class="label">System ID</div><div class="value" style="font-size:13px" id="systemId">—</div></div><div class="card"><div class="label">Memory records</div><div class="value" id="memoryCount">—</div></div><div class="card"><div class="label">Checkpoint</div><div class="value" style="font-size:13px" id="checkpoint">—</div></div><div class="card"><div class="label">Authority grants</div><div class="value" id="grantCount">0</div></div><div class="card"><div class="label">Q-Bay</div><div class="value">EXPERIMENTAL</div><div class="sub">configuration ≠ live validation</div></div><div class="card full"><div class="label">SYSTEM MAP</div><div class="flow" style="margin-top:13px"><span class="node">USER</span><span class="arrow">→</span><span class="node">SENSORS / FILES / WORKSPACE</span><span class="arrow">→</span><span class="node">CNS / CST STATE</span><span class="arrow">→</span><span class="node">MEMORY + R12</span><span class="arrow">→</span><span class="node">MODEL PROVIDER</span><span class="arrow">→</span><span class="node">POLICY / TOOLS</span><span class="arrow">→ WORLD ↺</span></div></div></div></section>
<section id="brain" class="view"><div class="grid"><div class="card full"><div class="label">BRAIN · CONVERSATION</div><div id="swapBanner" class="warning hidden" style="margin:10px 0">BRAIN CHANGED · SUBSTRATE PRESERVED</div><div class="chatlog" id="chatlog"></div><div class="composer"><textarea id="chatText" placeholder="Talk to your system…"></textarea><button id="sendChat">SEND</button></div><div class="sub">Every turn reports the exact configured provider. No silent inference fallback.</div></div></div></section>
<section id="bay" class="view"><div class="grid"><div class="card full"><div class="label">BRAIN BAY · PROVIDER CLOCK-IN</div><div class="fields" style="margin-top:12px"><label>Kind<select id="providerKind"><option value="reference">Reference fixture</option><option value="ollama">Ollama</option><option value="compatible">OpenAI-compatible</option></select></label><label>Model<input id="providerModel" value="COSMOS reference"></label><label>Base URL<input id="providerUrl" placeholder="http://127.0.0.1:11434"></label><label>API key environment variable<input id="providerEnv" placeholder="OPTIONAL_ENV_NAME"></label></div><label style="display:block;margin-top:10px"><input style="width:auto" type="checkbox" id="allowRemote"> Explicitly allow a configured HTTPS remote endpoint</label><button id="saveProvider" style="margin-top:10px">CLOCK IN BRAIN</button><div class="sub">Credential values are not accepted here. The profile stores only an environment-variable name.</div></div></div></section>
<section id="vision" class="view"><div class="grid"><div class="card wide"><div class="label">VISION · LOCAL CAMERA</div><video id="cameraPreview" class="camera" autoplay muted playsinline></video><canvas id="cameraCanvas" class="hidden"></canvas><div style="margin-top:10px"><button id="cameraOn">ENABLE CAMERA</button> <button id="cameraSample">SAMPLE BOUNDED OBSERVATION</button> <button id="cameraOff">STOP CAMERA</button></div></div><div class="card"><div class="label">Boundary</div><div class="value" id="cameraStatus">OFF</div><div class="sub">Camera-derived features are not vision understanding. Raw frames stay in this browser in the current implementation.</div></div></div></section>
<section id="listen" class="view"><div class="grid"><div class="card wide"><div class="label">LISTEN · LOCAL MICROPHONE</div><canvas id="audioScope" class="scope" width="900" height="180"></canvas><div style="margin-top:10px"><button id="micOn">ENABLE MIC</button> <button id="micSample">SEND FEATURE SAMPLE</button> <button id="micOff">STOP MIC</button></div></div><div class="card"><div class="label">LIVE MIC</div><div class="value" id="micStatus">OFF</div><div class="sub">Raw continuous audio is never posted by this UI. Local RMS features require explicit microphone authority.</div></div></div></section>
<section id="voice" class="view"><div class="grid"><div class="card full"><div class="label">VOICE · LOCAL BROWSER TTS</div><textarea id="voiceText" placeholder="Text to speak"></textarea><button id="speak">SPEAK LOCALLY</button> <button id="stopSpeak">STOP VOICE</button><div class="sub">Uses browser speechSynthesis. Authorized custom voice cloning is NOT ESTABLISHED in the current validated product path.</div></div></div></section>
<section id="reality" class="view"><div class="grid"><div class="card full"><div class="label">REALITY · SENSOR / BIO LOOP</div><div class="warning">Current browser surface accepts bounded normalized sensor events. Physical Reality Probe hardware remains separate physical validation. Bio observations are nonmedical.</div><pre id="realityOut">No live device stream connected.</pre></div></div></section>
<section id="memory" class="view"><div class="grid"><div class="card full"><div class="label">MEMORY VAULT</div><button id="refreshMemory">REFRESH</button><pre id="memoryOut">—</pre></div></div></section>
<section id="trace" class="view"><div class="grid"><div class="card full"><div class="label">SYNAPSE TRACE · SYSTEM EVENTS, NOT PRIVATE CHAIN-OF-THOUGHT</div><button id="refreshTrace">REFRESH</button><div id="traceOut"></div></div></div></section>
<section id="files" class="view"><div class="grid"><div class="card full"><div class="label">FILES · TEMPORARY LOCAL INSPECTION</div><input type="file" id="fileInput" multiple><pre id="fileOut">Choose files. This browser inspection does not silently make them permanent memory.</pre></div></div></section>
<section id="workspace" class="view"><div class="grid"><div class="card full"><div class="label">WORKSPACE</div><div class="warning">The current CYpher workspace engine is confined and read-only by default. This surface will never make repository write authority travel with a swapped model.</div><pre>Workspace connection is not activated until an explicit local root is selected through the host controller.</pre></div></div></section>
<section id="qbay" class="view"><div class="grid"><div class="card half"><div class="label">Q-BAY · IBM / AZURE</div><button id="refreshResources">CHECK CONFIGURATION</button><pre id="resourcesOut">—</pre></div><div class="card half"><div class="label">LIVE EXPERIMENTAL JOB</div><select id="qProvider"><option value="ibm">IBM hardware adapter</option><option value="azure">Azure IonQ simulator</option></select><input id="qShots" type="number" min="1" max="1024" value="128"><button id="qRun">SUBMIT AUTHORIZED JOB</button><div class="sub">Requires a separate quantum_live authority grant. Quantum provenance ≠ quantum advantage.</div></div></div></section>
<section id="connections" class="view"><div class="grid"><div class="card full"><div class="label">CONNECTIONS</div><pre id="connectionsOut">IBM / Azure status reports configuration only. Ollama and compatible model endpoints are configured in Brain Bay. Secret values remain host configuration.</pre></div></div></section>
<section id="authority" class="view"><div class="grid"><div class="card full"><div class="label">AUTHORITY · DOES NOT TRAVEL WITH MEMORY</div><div id="authorityList"></div></div></div></section>
<section id="settings" class="view"><div class="grid"><div class="card full"><div class="label">SETTINGS</div><div class="sub">Basic: chat, camera, mic, models, memory, voice. Advanced: sensors, workspace, storage, authority. Lab: CNS/R12/Q-Bay/provenance. Experimental labels stay visible.</div></div></div></section>
</main></div><script>
const sessionKey=__BEAST_SESSION__;let orbit=null,cameraStream=null,audioStream=null,audioCtx=null,analyser=null;
async function api(path,method='GET',body=null){const opt={method,headers:{'X-Beast-Session':sessionKey}};if(body!==null){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(body)}const r=await fetch(path,opt);let j={};try{j=await r.json()}catch{}if(!r.ok)throw new Error(j.error||('HTTP '+r.status));return j}
function show(view){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===view));document.querySelectorAll('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view))}document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>show(b.dataset.view));
function addMsg(role,text){const d=document.createElement('div');d.className='msg '+role;d.textContent=text;document.getElementById('chatlog').appendChild(d);d.scrollIntoView({block:'end'})}
async function loadOrbit(){orbit=await api('/api/orbit');const r=orbit.runtime;document.getElementById('systemId').textContent=r.system_id;document.getElementById('checkpoint').textContent=r.checkpoint_sha256.slice(0,20)+'…';document.getElementById('memoryCount').textContent=r.memory.memories;document.getElementById('grantCount').textContent=Object.values(orbit.authority).filter(Boolean).length;renderAuthority(orbit.authority);const p=await api('/api/provider');document.getElementById('brainValue').textContent=p.profile.model;document.getElementById('providerValue').textContent=p.profile.kind;document.getElementById('providerPill').textContent=p.profile.kind+' · '+p.profile.model;document.getElementById('cloudPill').textContent=orbit.authority.cloud?'CLOUD AUTHORIZED':'LOCAL BOUNDARY'}
function renderAuthority(a){const box=document.getElementById('authorityList');box.innerHTML='';Object.entries(a).forEach(([name,on])=>{const row=document.createElement('div');row.className='authority-row';const s=document.createElement('span');s.textContent=name+' · '+(on?'GRANTED':'DENIED');const b=document.createElement('button');b.textContent=on?'REVOKE':'GRANT';b.onclick=async()=>{await api('/api/authority','POST',{action:on?'revoke':'grant',name});await loadOrbit()};row.append(s,b);box.appendChild(row)})}
async function grant(name){await api('/api/authority','POST',{action:'grant',name});await loadOrbit()}async function revoke(name){try{await api('/api/authority','POST',{action:'revoke',name})}catch{}await loadOrbit()}
function localStopCamera(){if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null}document.getElementById('cameraPreview').srcObject=null;document.getElementById('cameraStatus').textContent='OFF'}function localStopMic(){if(audioStream){audioStream.getTracks().forEach(t=>t.stop());audioStream=null}if(audioCtx){audioCtx.close();audioCtx=null}analyser=null;document.getElementById('micStatus').textContent='OFF'}
document.getElementById('masterStop').onclick=async()=>{localStopCamera();localStopMic();speechSynthesis.cancel();await api('/api/authority','POST',{action:'master_stop'});await loadOrbit()};
document.getElementById('sendChat').onclick=async()=>{const t=document.getElementById('chatText'),text=t.value.trim();if(!text)return;addMsg('user',text);t.value='';try{const j=await api('/api/chat','POST',{text});addMsg('assistant',j.result.response);document.getElementById('voiceText').value=j.result.response;document.getElementById('swapBanner').classList.toggle('hidden',!j.brain_changed);await loadOrbit()}catch(e){addMsg('assistant','Request failed: '+e.message)}};
document.getElementById('saveProvider').onclick=async()=>{const body={kind:document.getElementById('providerKind').value,model:document.getElementById('providerModel').value,base_url:document.getElementById('providerUrl').value,allow_remote:document.getElementById('allowRemote').checked,api_key_env:document.getElementById('providerEnv').value||null};try{const j=await api('/api/provider','POST',body);if(j.authority_reset)alert('Brain changed. Authority grants were reset and must be explicitly re-granted.');await loadOrbit();show('brain')}catch(e){alert(e.message)}};
async function startCamera(){if(cameraStream)return;await grant('camera');try{cameraStream=await navigator.mediaDevices.getUserMedia({video:true,audio:false});document.getElementById('cameraPreview').srcObject=cameraStream;document.getElementById('cameraStatus').textContent='CAMERA LIVE'}catch(e){await revoke('camera');throw e}}async function stopCamera(){localStopCamera();await revoke('camera')}
async function sampleCamera(){if(!cameraStream)throw new Error('camera is off');const v=document.getElementById('cameraPreview'),c=document.getElementById('cameraCanvas');c.width=Math.max(1,v.videoWidth||320);c.height=Math.max(1,v.videoHeight||180);const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(v,0,0,c.width,c.height);const d=x.getImageData(0,0,c.width,c.height).data;let sum=0,n=0;const stride=Math.max(4,Math.floor(d.length/4096/4)*4);for(let i=0;i<d.length;i+=stride){sum+=(d[i]+d[i+1]+d[i+2])/(3*255);n++}const mean=n?sum/n:0;return api('/api/event','POST',{modality:'camera',event:{schema:'sensor-event-v1',source:'software-event',text:JSON.stringify({source:'browser-camera',mode:'local-brightness-summary',mean}),features:[mean*2-1]}})}
document.getElementById('cameraOn').onclick=()=>startCamera().catch(e=>alert(e.message));document.getElementById('cameraOff').onclick=()=>stopCamera();document.getElementById('cameraSample').onclick=()=>sampleCamera().catch(e=>alert(e.message));
function drawAudio(){if(!analyser)return;const a=new Uint8Array(analyser.fftSize);analyser.getByteTimeDomainData(a);const c=document.getElementById('audioScope'),x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);x.beginPath();for(let i=0;i<a.length;i++){const px=i/(a.length-1)*c.width,py=a[i]/255*c.height;i?x.lineTo(px,py):x.moveTo(px,py)}x.strokeStyle='#79ded5';x.stroke();requestAnimationFrame(drawAudio)}
async function startMic(){if(audioStream)return;await grant('microphone');try{audioStream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});audioCtx=new AudioContext();analyser=audioCtx.createAnalyser();analyser.fftSize=1024;audioCtx.createMediaStreamSource(audioStream).connect(analyser);document.getElementById('micStatus').textContent='MIC LIVE';drawAudio()}catch(e){await revoke('microphone');throw e}}async function stopMic(){localStopMic();await revoke('microphone')}
async function sampleMic(){if(!analyser)throw new Error('microphone is off');const a=new Float32Array(analyser.fftSize);analyser.getFloatTimeDomainData(a);let s=0;for(const v of a)s+=v*v;const rms=Math.sqrt(s/a.length),bounded=Math.max(-1,Math.min(1,rms*2-1));return api('/api/event','POST',{modality:'microphone',event:{schema:'sensor-event-v1',source:'software-event',text:JSON.stringify({source:'browser-microphone',mode:'local-rms-feature',rms}),features:[bounded]}})}
document.getElementById('micOn').onclick=()=>startMic().catch(e=>alert(e.message));document.getElementById('micOff').onclick=()=>stopMic();document.getElementById('micSample').onclick=()=>sampleMic().catch(e=>alert(e.message));
document.getElementById('speak').onclick=()=>{speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(document.getElementById('voiceText').value))};document.getElementById('stopSpeak').onclick=()=>speechSynthesis.cancel();
document.getElementById('refreshMemory').onclick=async()=>document.getElementById('memoryOut').textContent=JSON.stringify(await api('/api/memory'),null,2);document.getElementById('refreshTrace').onclick=async()=>{const j=await api('/api/trace'),o=document.getElementById('traceOut');o.innerHTML='';j.events.forEach(e=>{const d=document.createElement('div');d.className='trace-node';d.textContent='#'+e.sequence+' · '+e.stages.join(' → ')+' · '+(e.model.provider||'system');o.appendChild(d)})};document.getElementById('refreshResources').onclick=async()=>document.getElementById('resourcesOut').textContent=JSON.stringify(await api('/api/resources'),null,2);
document.getElementById('qRun').onclick=async()=>{if(!confirm('Submit one explicitly authorized experimental quantum workload?'))return;try{await grant('quantum_live');const j=await api('/api/quantum','POST',{provider:document.getElementById('qProvider').value,shots:Number(document.getElementById('qShots').value)});document.getElementById('resourcesOut').textContent=JSON.stringify(j,null,2)}catch(e){alert(e.message)}};
document.getElementById('fileInput').onchange=async ev=>{const out=[];for(const f of ev.target.files){const b=await f.arrayBuffer(),h=await crypto.subtle.digest('SHA-256',b);out.push({name:f.name,bytes:f.size,sha256:[...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join(''),persistence:'TEMPORARY_BROWSER_ONLY'})}document.getElementById('fileOut').textContent=JSON.stringify(out,null,2)};
window.addEventListener('beforeunload',()=>{localStopCamera();localStopMic()});loadOrbit().catch(e=>addMsg('assistant','Runtime unavailable: '+e.message));
</script></body></html>'''
